INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00ixoqcxv085ax0v', NULL, 'How fast do orders start?', 'Most services start within 0-30 minutes. Large orders are drip-fed automatically to keep accounts safe.', 'Orders', 0);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00iyoqcxg6oo31s3', NULL, 'What payment methods do you accept?', 'Credit/debit cards, PayPal, Crypto (Binance Pay, USDT) and bank transfer.', 'Payments', 1);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00izoqcx2brcojj5', NULL, 'Do you offer refunds?', 'If we cannot deliver your order, it is refunded to your balance automatically. Partial deliveries are refunded pro-rata.', 'Payments', 2);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00j0oqcx4rpwyrgv', NULL, 'Is there an API?', 'Yes — a standard SMM API v2 endpoint is included with every account, plus API docs in your portal.', 'API', 3);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00j1oqcxm4z1mx0i', NULL, 'Can I resell with my own brand?', 'Absolutely. Buy a reseller plan and you get your own branded panel on a free subdomain or your custom domain.', 'Reseller', 4);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtw1relw00j2oqcxbh50sfp9', NULL, 'Do services come with refill?', 'Most services include a 30-day refill guarantee — check the refill badge on each service.', 'Orders', 5);
